package com.raasta.app.planner

import android.content.Context
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * Demo corridor data, generated by tools/corridor/build_corridor.py from real sources
 * (PMPML timetable, official metro fares, OpenStreetMap, OSRM). See [sources].
 */
@Serializable
data class Corridor(
    val corridor: String,
    val generatedOn: String,
    val sources: List<Source>,
    val fares: Fares,
    val metro: Metro,
    val assumptions: Assumptions,
    val origins: List<Origin>,
    val destinations: List<Destination>,
    val autoDirect: List<AutoDirect>,
    val recoveryPoints: List<RecoveryPoint> = emptyList(),
) {
    fun origin(id: String): Origin = origins.first { it.id == id }
    fun recoveryPoint(id: String): RecoveryPoint = recoveryPoints.first { it.id == id }

    /** Every bus route and boarding stop in the corridor, once each. */
    fun busAccesses(): List<BusAccess> =
        origins.flatMap { it.accessToMetro.filterIsInstance<BusAccess>() }
            .distinctBy { it.route to it.boardStop.name }
    fun destination(id: String): Destination = destinations.first { it.id == id }
    fun station(name: String): MetroStation = metro.stations.first { it.name == name }
    fun autoDirect(originId: String, destinationId: String): AutoDirect =
        autoDirect.first { it.origin == originId && it.destination == destinationId }

    companion object {
        private val json = Json {
            ignoreUnknownKeys = true
            classDiscriminator = "type"
        }

        fun parse(text: String): Corridor = json.decodeFromString(serializer(), text)

        fun load(context: Context): Corridor =
            parse(context.assets.open("corridor.json").bufferedReader().use { it.readText() })
    }
}

@Serializable
data class Source(
    val id: String,
    val title: String,
    val url: String,
    val retrieved: String,
    val note: String,
)

@Serializable
data class Fares(val pmpmlFareSlabs: List<FareSlab>, val autoFare: AutoFare)

@Serializable
data class FareSlab(val upToKm: Double, val fare: Int)

@Serializable
data class AutoFare(
    val baseFare: Int,
    val baseKm: Double,
    val perKm: Int,
    val nightSurchargePercent: Int,
    val nightStart: String,
    val nightEnd: String,
)

@Serializable
data class Metro(
    val line: String,
    val transferStation: String,
    val stations: List<MetroStation>,
    val service: MetroService,
)

@Serializable
data class MetroStation(
    val name: String,
    val lat: Double,
    val lon: Double,
    val fareFromRamwadi: Int,
    val kmFromRamwadi: Double,
)

@Serializable
data class MetroService(
    val firstTrain: String,
    val lastTrainEarliest: String,
    val lastTrainLatest: String,
    val headwayPeakMin: Double,
    val headwayOffPeakMin: Double,
    val peakWindows: List<List<String>>,
)

@Serializable
data class Assumptions(
    val metroAvgSpeedKmh: Double,
    val stationEntryMin: Double,
    val autoAvgSpeedKmh: Double,
    val autoPickupWaitMin: Double,
)

@Serializable
data class Place(val name: String, val lat: Double, val lon: Double)

@Serializable
data class Origin(
    val id: String,
    val name: String,
    val lat: Double,
    val lon: Double,
    val accessToMetro: List<AccessOption>,
)

/** How to get from an origin to the transfer metro station. */
@Serializable
sealed interface AccessOption

@Serializable
@SerialName("bus")
data class BusAccess(
    val route: String,
    val routeName: String,
    val boardStop: Place,
    val alightStop: Place,
    val rideKm: Double,
    val rideMin: Double,
    /** Published departures from [boardStop], "HH:MM". */
    val departures: List<String>,
    val medianHeadwayMin: Double? = null,
    val walkToStopM: Int,
    val walkToStopMin: Double,
    val walkToStationM: Int,
    val walkToStationMin: Double,
) : AccessOption

@Serializable
@SerialName("auto")
data class AutoAccess(val km: Double, val freeFlowMin: Double) : AccessOption

@Serializable
data class Destination(
    val id: String,
    val name: String,
    val lat: Double,
    val lon: Double,
    val metroStation: String,
    val walkFromStationM: Int,
    val walkFromStationMin: Double,
)

/** A bus stop where a rider can be stranded when their bus does not come. */
@Serializable
data class RecoveryPoint(
    val id: String,
    val name: String,
    val lat: Double,
    val lon: Double,
    /** Routes that board at this stop. */
    val routes: List<String>,
    val walksToStops: List<StopWalk>,
    val autoToTransfer: AutoAccess,
    val autoToDestinations: List<DestinationRide>,
) {
    fun walkTo(stopName: String): StopWalk? = walksToStops.firstOrNull { it.to == stopName }
}

@Serializable
data class StopWalk(val to: String, val m: Int, val min: Double)

@Serializable
data class DestinationRide(val destination: String, val km: Double, val freeFlowMin: Double)

@Serializable
data class AutoDirect(
    val origin: String,
    val destination: String,
    val km: Double,
    val freeFlowMin: Double,
)
